/* RuneScape set additions — cards appended after runescape-3.js.
   (runescape-3.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'runescape-3.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('runescape-3');
  if (!S) return;
  var extra = [{"name":"Crafting","rarity":"common","id":"crafting","subtitle":"Skills","details":"Working leather, gems, glass, pottery, and gold into jewellery, armour, and useful objects at wheels, furnaces, and looms.","image":"https://runescape.wiki/images/thumb/Crafting_cape_detail.png/640px-Crafting_cape_detail.png"},{"name":"Fletching","rarity":"common","id":"fletching","subtitle":"Skills","details":"Carving logs into bows, arrows, bolts, and crossbows, supplying rangers with the ammunition their training consumes daily.","image":"https://runescape.wiki/images/thumb/Fletching_cape_detail.png/640px-Fletching_cape_detail.png"},{"name":"Fishing","rarity":"common","id":"fishing","subtitle":"Skills","details":"Casting nets, harpoons, and cages into seas and rivers for food that cooks into the healing supplies of every adventure.","image":"https://runescape.wiki/images/thumb/Fishing_cape_detail.png/640px-Fishing_cape_detail.png"},{"name":"Cooking","rarity":"common","id":"cooking","subtitle":"Skills","details":"Preparing raw food over fires and ranges so it can heal in battle, from simple shrimps to elaborate multi-part dishes.","image":"https://runescape.wiki/images/thumb/Cooking_cape_detail.png/640px-Cooking_cape_detail.png"},{"name":"Firemaking","rarity":"common","id":"firemaking","subtitle":"Skills","details":"Lighting logs for light and warmth, building bonfires that boost health, and burning pyre logs to honour fallen heroes.","image":"https://runescape.wiki/images/thumb/Firemaking_cape_detail.png/512px-Firemaking_cape_detail.png"},{"name":"Woodcutting","rarity":"common","id":"woodcutting","subtitle":"Skills","details":"Felling trees from humble oaks to crystal giants, gathering the logs that feed Fletching, Firemaking, and Construction.","image":"https://runescape.wiki/images/thumb/Woodcutting_cape_detail.png/640px-Woodcutting_cape_detail.png"},{"name":"Giant Mole","rarity":"common","id":"giant-mole","subtitle":"Bosses","details":"A mutated mole burrowing beneath Falador Park, digging between caverns and shaking the ground as it flees.","image":"https://runescape.wiki/images/thumb/Giant_mole.png/640px-Giant_mole.png"},{"name":"Barrows Brothers","rarity":"common","id":"barrows-brothers","subtitle":"Bosses","details":"Six wight brothers entombed beneath Mort'ton, looted in their crypts for barrows armour and weapons.","image":"https://runescape.wiki/images/thumb/Barrows_Brothers_1920x1200.jpg/640px-Barrows_Brothers_1920x1200.jpg"},{"name":"Skeletal Horror","rarity":"common","id":"skeletal-horror","subtitle":"Bosses","details":"A patchwork horror of bones near the Odd Old Man's quarry, rebuilt from pieces collected across the world.","image":"https://runescape.wiki/images/thumb/Skeletal_Horror.png/640px-Skeletal_Horror.png"},{"name":"Delrith","rarity":"common","id":"delrith","subtitle":"Bosses","details":"The demon summoned beneath Varrock by Dark Wizards, banished in Demon Slayer with Silverlight's incantation.","image":"https://runescape.wiki/images/thumb/Delrith.png/640px-Delrith.png"},{"name":"Count Draynor","rarity":"common","id":"count-draynor","subtitle":"Bosses","details":"The vampyre count haunting Draynor Manor, faced in Vampyre Slayer armed with a stake, hammer and garlic.","image":"https://runescape.wiki/images/Count_Draynor.png"},{"name":"Melzar the Mad","rarity":"common","id":"melzar-the-mad","subtitle":"Bosses","details":"A mad wizard in his maze south of Rimmington, guarding a map piece with zombies, ghosts, demons and a dragon.","image":"https://runescape.wiki/images/Melzar_the_Mad.png"},{"name":"Chronozon","rarity":"common","id":"chronozon","subtitle":"Bosses","details":"A demon in Edgeville Dungeon who must be weakened with all four elemental blast spells in Family Crest.","image":"https://runescape.wiki/images/thumb/Chronozon.png/640px-Chronozon.png"},{"name":"Jungle Demon","rarity":"common","id":"jungle-demon","subtitle":"Bosses","details":"A demon summoned on Ape Atoll during Monkey Madness, fought from a bridge while gnomes aid the exile.","image":"https://runescape.wiki/images/Jungle_demon.png"},{"name":"Black Knight Titan","rarity":"common","id":"black-knight-titan","subtitle":"Bosses","details":"A towering black knight on the Holy Grail quest, blocking the Fisher King's realm until Excalibur strikes.","image":"https://runescape.wiki/images/thumb/Black_knight_titan.png/640px-Black_knight_titan.png"},{"name":"Dessous","rarity":"common","id":"dessous","subtitle":"Bosses","details":"A vampyric noble in Desert Treasure, rising from his coffin near Canifis to fight with blood and bats.","image":"https://runescape.wiki/images/thumb/Dessous.png/640px-Dessous.png"},{"name":"Kamil","rarity":"common","id":"kamil","subtitle":"Bosses","details":"A warrior of ice in Desert Treasure who freezes travellers solid on the long, frozen path to his icy arena.","image":"https://runescape.wiki/images/thumb/Kamil.png/512px-Kamil.png"},{"name":"Damis","rarity":"common","id":"damis","subtitle":"Bosses","details":"A shadow warrior in Desert Treasure, fought twice in a pitch-dark cave for the coveted diamond of shadow.","image":"https://runescape.wiki/images/thumb/Damis.png/640px-Damis.png"},{"name":"Fareed","rarity":"common","id":"fareed","subtitle":"Bosses","details":"A fire warrior in Desert Treasure, met in a smoky, superheated cave to claim the coveted diamond of smoke.","image":"https://runescape.wiki/images/Fareed.png"},{"name":"Nezikchened","rarity":"common","id":"nezikchened","subtitle":"Bosses","details":"An ogre shaman's demon in Legends' Quest, possessing Ungadulu and fighting with draining prayer attacks.","image":"https://runescape.wiki/images/Nezikchened.png"},{"name":"Agoroth","rarity":"common","id":"agoroth","subtitle":"Bosses","details":"A crassian sea monster lurking in the caves beneath Ashdale, fought during a shadowy attack on the island town.","image":"https://runescape.wiki/images/thumb/Agoroth.png/640px-Agoroth.png"},{"name":"Blink","rarity":"common","id":"blink","subtitle":"Bosses","details":"A frantic human experiment in Daemonheim who sprints between pillars, daring ranged and magic attacks.","image":"https://runescape.wiki/images/thumb/Blink.png/640px-Blink.png"},{"name":"Stomp","rarity":"common","id":"stomp","subtitle":"Bosses","details":"A behemoth in Daemonheim that shelters under falling rocks while its crystals channel healing energy.","image":"https://runescape.wiki/images/thumb/Stomp.png/640px-Stomp.png"},{"name":"Rammernaut","rarity":"common","id":"rammernaut","subtitle":"Bosses","details":"A hulking brute in Daemonheim who charges across the room, stomps the floor and clears prayers with his mace.","image":"https://runescape.wiki/images/thumb/Rammernaut.png/640px-Rammernaut.png"},{"name":"Sagittare","rarity":"common","id":"sagittare","subtitle":"Bosses","details":"A centaur-like ranger in Daemonheim, teleporting around his arena while raining arrows on intruders.","image":"https://runescape.wiki/images/Sagittare.png"},{"name":"Bulwark Beast","rarity":"common","id":"bulwark-beast","subtitle":"Bosses","details":"An armoured behemoth in Daemonheim whose thick plating must be picked away before real damage can land.","image":"https://runescape.wiki/images/thumb/Bulwark_beast.png/640px-Bulwark_beast.png"},{"name":"Lexicus Runewright","rarity":"common","id":"lexicus-runewright","subtitle":"Bosses","details":"A bookish mage in Daemonheim who summons living books, hurls tomes and vanishes in a swirl of pages.","image":"https://runescape.wiki/images/Lexicus_Runewright.png"},{"name":"Astea Frostweb","rarity":"common","id":"astea-frostweb","subtitle":"Bosses","details":"An ice sorceress in Daemonheim who freezes the floor, summons icy spiders and switches her prayers often.","image":"https://runescape.wiki/images/Astea_Frostweb.png"},{"name":"Har'Lakk the Riftsplitter","rarity":"common","id":"har-lakk-the-riftsplitter","subtitle":"Bosses","details":"A demon in Daemonheim who tears glowing rifts into the arena, draining prayer beneath a rain of debris.","image":"https://runescape.wiki/images/Har%27Lakk_the_Riftsplitter.png"},{"name":"Yk'Lagor the Thunderous","rarity":"common","id":"yk-lagor-the-thunderous","subtitle":"Bosses","details":"A thunderous demon in Daemonheim, freed from his shaman captors to crush and blast his former jailers.","image":"https://runescape.wiki/images/Yk%27Lagor_the_Thunderous.png"},{"name":"Shadow-Forger Ihlakhizan","rarity":"common","id":"shadow-forger-ihlakhizan","subtitle":"Bosses","details":"A dragon-like forger in Daemonheim that breathes shadow, darkens the room and forges darkness as it fights.","image":"https://runescape.wiki/images/thumb/Shadow-Forger_Ihlakhizan.png/640px-Shadow-Forger_Ihlakhizan.png"},{"name":"Night-gazer Khighorahk","rarity":"common","id":"night-gazer-khighorahk","subtitle":"Bosses","details":"A floating stalker in Daemonheim fought by torchlight, left vulnerable only when all its pillars are lit.","image":"https://runescape.wiki/images/thumb/Night-gazer_Khighorahk.png/640px-Night-gazer_Khighorahk.png"},{"name":"Cook's Assistant","rarity":"common","id":"cook-s-assistant","subtitle":"Quests","details":"Gather milk, flour and an egg for the Lumbridge Cook so he can bake a birthday cake for Duke Horacio without ruining the day.","image":"https://runescape.wiki/images/thumb/Cook%27s_Assistant.png/640px-Cook%27s_Assistant.png?b7959"},{"name":"Rune Mysteries","rarity":"common","id":"rune-mysteries","subtitle":"Quests","details":"Deliver a mysterious package from Duke Horacio to Aubury in Varrock, and uncover the wizards' secret of rune stone crafting.","image":"https://runescape.wiki/images/thumb/Rune_Mysteries.png/640px-Rune_Mysteries.png?290e3"},{"name":"The Restless Ghost","rarity":"common","id":"the-restless-ghost","subtitle":"Quests","details":"Help Father Aereck in Lumbridge Church find why a ghost haunts the graveyard crypt, and lay its restless spirit to rest.","image":"https://runescape.wiki/images/thumb/The_Restless_Ghost.png/640px-The_Restless_Ghost.png?21a7f"},{"name":"Ernest the Chicken","rarity":"common","id":"ernest-the-chicken","subtitle":"Quests","details":"Rescue Ernest from Professor Oddenstein's machine in Draynor Manor, after it turned the unlucky visitor into a chicken.","image":"https://runescape.wiki/images/thumb/Ernest_the_Chicken.png/640px-Ernest_the_Chicken.png?cfae4"},{"name":"Imp Catcher","rarity":"common","id":"imp-catcher","subtitle":"Quests","details":"Recover Wizard Grayzag's stolen magic beads from imps across Gielinor and return the red, black, white and yellow beads to him.","image":"https://runescape.wiki/images/thumb/Imp_Catcher.png/640px-Imp_Catcher.png?cc9f9"},{"name":"Sheep Shearer","rarity":"common","id":"sheep-shearer","subtitle":"Quests","details":"Shear Fred the Farmer's black sheep north of Lumbridge, spin twenty balls of black wool, and return them for his reward.","image":"https://runescape.wiki/images/thumb/Sheep_Shearer_%28miniquest%29.png/640px-Sheep_Shearer_%28miniquest%29.png?33899"},{"name":"Doric's Quest","rarity":"common","id":"doric-s-quest","subtitle":"Quests","details":"Help Doric the dwarf near Falador by mining copper, tin and iron ores so he can keep his anvils and pickaxes in business.","image":"https://runescape.wiki/images/thumb/Doric%27s_Quest.png/640px-Doric%27s_Quest.png"},{"name":"Witch's Potion","rarity":"common","id":"witch-s-potion","subtitle":"Quests","details":"Gather a rat's tail, burnt meat, an eye of newt and an onion for Hetty the Witch in Rimmington, then drink from her cauldron.","image":"https://runescape.wiki/images/thumb/Witch%27s_Potion_%28miniquest%29.png/640px-Witch%27s_Potion_%28miniquest%29.png?50d78"},{"name":"Goblin Diplomacy","rarity":"common","id":"goblin-diplomacy","subtitle":"Quests","details":"Settle a goblin armour colour dispute in Goblin Village by dyeing goblin mail orange and blue for Generals Bentnoze and Wartface.","image":"https://runescape.wiki/images/thumb/Goblin_Diplomacy.png/640px-Goblin_Diplomacy.png?9d0ae"},{"name":"Pirate's Treasure","rarity":"common","id":"pirate-s-treasure","subtitle":"Quests","details":"Follow Redbeard Frank's clues from Port Sarim to a buried chest in Falador Park, smuggling Karamjan rum past the customs officers.","image":"https://runescape.wiki/images/thumb/Pirate%27s_Treasure.png/640px-Pirate%27s_Treasure.png"},{"name":"Demon Slayer","rarity":"common","id":"demon-slayer","subtitle":"Quests","details":"Gather the three keys to Silverlight in Varrock, claim the blessed sword, and banish the demon Delrith before he destroys the city.","image":"https://runescape.wiki/images/thumb/Demon_Slayer.png/640px-Demon_Slayer.png?87cd1"},{"name":"Vampyre Slayer","rarity":"common","id":"vampyre-slayer","subtitle":"Quests","details":"Help Dr Harlow in Varrock arm you with a stake, hammer and garlic, then face Count Draynor in his manor south of Draynor Village.","image":"https://runescape.wiki/images/thumb/Vampyre_Slayer.png/640px-Vampyre_Slayer.png?d42c3"},{"name":"Shield of Arrav","rarity":"common","id":"shield-of-arrav","subtitle":"Quests","details":"Join the Phoenix Gang or Black Arm Gang in Varrock, recover both halves of the Shield of Arrav, and claim the royal reward.","image":"https://runescape.wiki/images/thumb/Shield_of_Arrav.png/640px-Shield_of_Arrav.png?39f01"},{"name":"Prince Ali Rescue","rarity":"common","id":"prince-ali-rescue","subtitle":"Quests","details":"Disguise Prince Ali in Al Kharid, free him from Lady Keli's prison in Draynor, and return him safely across the desert gate.","image":"https://runescape.wiki/images/thumb/Prince_Ali_Rescue.png/640px-Prince_Ali_Rescue.png?ab841"},{"name":"Black Knights' Fortress","rarity":"common","id":"black-knights-fortress","subtitle":"Quests","details":"Infiltrate the Black Knights' Fortress north of Falador, listen to their secret meeting, and sabotage their invulnerability potion.","image":"https://runescape.wiki/images/thumb/Black_Knights%27_Fortress.png/640px-Black_Knights%27_Fortress.png?1a120"},{"name":"The Knight's Sword","rarity":"common","id":"the-knight-s-sword","subtitle":"Quests","details":"Help Sir Vyvin's squire in Falador recover a lost sword by having Thurgo the dwarf smith a replica from blurite ore.","image":"https://runescape.wiki/images/thumb/The_Knight%27s_Sword.png/640px-The_Knight%27s_Sword.png?b9046"},{"name":"Druidic Ritual","rarity":"common","id":"druidic-ritual","subtitle":"Quests","details":"Gather raw bear meat, rat meat, chicken and beef for Sanfew in Taverley so the druids can complete their ritual at the stone circle.","image":"https://runescape.wiki/images/thumb/Druidic_Ritual.png/640px-Druidic_Ritual.png?cbb91"},{"name":"Jungle Potion","rarity":"common","id":"jungle-potion","subtitle":"Quests","details":"Help Trufitus in Tai Bwo Wannai gather jungle herbs for a communion potion, braving broodoo victims and the Kharazi Jungle.","image":"https://runescape.wiki/images/thumb/Jungle_Potion.png/640px-Jungle_Potion.png?57069"},{"name":"Nature Spirit","rarity":"common","id":"nature-spirit","subtitle":"Quests","details":"Help Filliman Tarlock in Mort Myre Swamp become a nature spirit, blessing a silver sickle to fight the ghasts haunting the swamp.","image":"https://runescape.wiki/images/thumb/Nature_Spirit.png/640px-Nature_Spirit.png?60319"},{"name":"Priest in Peril","rarity":"common","id":"priest-in-peril","subtitle":"Quests","details":"Rescue Drezel from the Temple of Paterdomus, where King Roald's men hold him prisoner above the River Salve east of Varrock.","image":"https://runescape.wiki/images/thumb/Priest_in_Peril.png/640px-Priest_in_Peril.png?b3926"},{"name":"Recruitment Drive","rarity":"common","id":"recruitment-drive","subtitle":"Quests","details":"Pass a series of logic, memory and combat trials set by Sir Tiffy Cashien in Falador to join the Temple Knights as a recruit.","image":"https://runescape.wiki/images/thumb/Recruitment_Drive.png/640px-Recruitment_Drive.png?9bf83"},{"name":"The Lost Tribe","rarity":"common","id":"the-lost-tribe","subtitle":"Quests","details":"Investigate a cave beneath Lumbridge, meet the cave goblin Dorgeshuun tribe, and stop a war brewing with Duke Horacio's court.","image":"https://runescape.wiki/images/thumb/The_Lost_Tribe.png/640px-The_Lost_Tribe.png?865b3"},{"name":"Death to the Dorgeshuun","rarity":"common","id":"death-to-the-dorgeshuun","subtitle":"Quests","details":"Disguise yourself as a goblin, join Zanik to spy on H.A.M. in their hideout, and foil their plan to flood the Dorgeshuun city.","image":"https://runescape.wiki/images/thumb/Death_to_the_Dorgeshuun.png/640px-Death_to_the_Dorgeshuun.png?0efd1"},{"name":"Lumbridge","rarity":"common","id":"lumbridge","subtitle":"Locations","details":"The starting town on the River Lum, with a castle, a church, farms and goblins nearby, where most adventurers first arrive in Gielinor.","image":"https://runescape.wiki/images/thumb/Lumbridge.png/640px-Lumbridge.png"},{"name":"Varrock","rarity":"common","id":"varrock","subtitle":"Locations","details":"The capital of Misthalin, a large city with a palace, a museum, shops and sewers, ruled by King Roald from Varrock Palace.","image":"https://runescape.wiki/images/thumb/Varrock.png/640px-Varrock.png"},{"name":"Falador","rarity":"common","id":"falador","subtitle":"Locations","details":"The white-walled capital of Asgarnia, home of the White Knights, with a park, a party room, a mine entrance and a great castle.","image":"https://runescape.wiki/images/thumb/Falador.png/640px-Falador.png"},{"name":"Al Kharid","rarity":"common","id":"al-kharid","subtitle":"Locations","details":"A desert city on the Kharidian border, with a palace, a scimitar shop, a furnace and tanner, reached through the Lumbridge toll gate.","image":"https://runescape.wiki/images/thumb/Al_Kharid.png/640px-Al_Kharid.png"},{"name":"Draynor Village","rarity":"common","id":"draynor-village","subtitle":"Locations","details":"A small village between Lumbridge and Port Sarim, with a market, a bank, a manor to the north and a jail famous for its sewers.","image":"https://runescape.wiki/images/thumb/NewDraynor.png/640px-NewDraynor.png"},{"name":"Port Sarim","rarity":"common","id":"port-sarim","subtitle":"Locations","details":"A busy port south of Falador, with ships to Karamja, Entrana and the Void Knights, plus a jail, a jewellery shop and fishing stores.","image":"https://runescape.wiki/images/thumb/Port_Sarim.png/640px-Port_Sarim.png"},{"name":"Rimmington","rarity":"common","id":"rimmington","subtitle":"Locations","details":"A quiet village south-west of Falador, with a crafting shop, a willow copse and a portal to player-owned houses and the Clan Camp.","image":"https://runescape.wiki/images/thumb/Rimmington_view.png/640px-Rimmington_view.png"},{"name":"Edgeville","rarity":"common","id":"edgeville","subtitle":"Locations","details":"A town on the edge of the Wilderness, with a bank, a furnace, a general store and a dungeon entrance beneath a yew-lined main street.","image":"https://runescape.wiki/images/thumb/Edgeville.png/640px-Edgeville.png"},{"name":"Barbarian Village","rarity":"common","id":"barbarian-village","subtitle":"Locations","details":"A Fremennik outpost on the River Lum west of Varrock, also called Gunnarsgrunn, with a smith, a potter and the Stronghold of Security.","image":"https://runescape.wiki/images/thumb/Barbarian_Village.png/640px-Barbarian_Village.png"},{"name":"Burthorpe","rarity":"common","id":"burthorpe","subtitle":"Locations","details":"A military town in Asgarnia at the foot of Death Plateau, home to the Burthorpe Games Room, a heroes' guild road and troll defences.","image":"https://runescape.wiki/images/thumb/Burthorpe.png/640px-Burthorpe.png"},{"name":"Taverley","rarity":"common","id":"taverley","subtitle":"Locations","details":"A druidic town west of Burthorpe, with a summoning obelisk, a herblore shop, a crystal chest and the gate to the Taverley Dungeon.","image":"https://runescape.wiki/images/thumb/Taverley.png/640px-Taverley.png"},{"name":"Catherby","rarity":"common","id":"catherby","subtitle":"Locations","details":"A fishing town on the coast east of White Wolf Mountain, with trawlers, a farming patch, a candle shop and a charter ship dock.","image":"https://runescape.wiki/images/thumb/Catherby.png/640px-Catherby.png"},{"name":"Seers' Village","rarity":"common","id":"seers-village","subtitle":"Locations","details":"A village in Kandarin known for its seers, with a courthouse, a spinning wheel, flax fields and the start of the Camelot quest lands.","image":"https://runescape.wiki/images/thumb/Seers%27_Village.png/640px-Seers%27_Village.png"},{"name":"Ardougne","rarity":"common","id":"ardougne","subtitle":"Locations","details":"The capital of Kandarin, split by a river into East and West Ardougne, with a market, a zoo, a castle and a plague divide between them.","image":"https://runescape.wiki/images/thumb/East_Ardougne.png/640px-East_Ardougne.png"},{"name":"Yanille","rarity":"common","id":"yanille","subtitle":"Locations","details":"A walled town in southern Kandarin beside the ogre lands, with a bank, a magic guild, a watchtower and a dungeon beneath its streets.","image":"https://runescape.wiki/images/thumb/Yanille.png/640px-Yanille.png"},{"name":"Tree Gnome Stronghold","rarity":"common","id":"tree-gnome-stronghold","subtitle":"Locations","details":"A gnome homeland north-west of Ardougne, centred on the Grand Tree, with glider pilots, tortoise training and a spirit tree network.","image":"https://runescape.wiki/images/thumb/Tree_Gnome_Stronghold_aerial.png/640px-Tree_Gnome_Stronghold_aerial.png"},{"name":"Entrana","rarity":"common","id":"entrana","subtitle":"Locations","details":"A holy island ruled by the church of Saradomin, where weapons and armour are banned, with a church, a brewery and a Law Altar portal.","image":"https://runescape.wiki/images/thumb/Entrana.png/640px-Entrana.png"},{"name":"Wizard's Tower","rarity":"common","id":"wizard-s-tower","subtitle":"Locations","details":"A tall tower south of Draynor Village, home to wizards of the Wizards' Tower, with a runecrafting guild above and a bridge to the mainland.","image":"https://runescape.wiki/images/thumb/Wizards%27_Tower.png/640px-Wizards%27_Tower.png"},{"name":"Champions' Guild","rarity":"common","id":"champions-guild","subtitle":"Locations","details":"A guild south of Varrock for proven adventurers, with a scimitar shop, a basement of puzzles and the start of Dragon Slayer at its door.","image":"https://runescape.wiki/images/thumb/Champions%27_Guild_exterior.png/640px-Champions%27_Guild_exterior.png"},{"name":"Heroes' Guild","rarity":"common","id":"heroes-guild","subtitle":"Locations","details":"A guild north of Taverley for heroes, with a fountain of heroism for glory amulets, a dragon battleaxe shop and a gem rock below.","image":"https://runescape.wiki/images/thumb/Heroes%27_Guild.png/640px-Heroes%27_Guild.png"},{"name":"Tai Bwo Wannai","rarity":"common","id":"tai-bwo-wannai","subtitle":"Locations","details":"A jungle village in central Karamja, built among palm trees with longhouses, a general store, a fence of hardwood and the Trio villages.","image":"https://runescape.wiki/images/thumb/Tai_Bwo_Wannai_Village.png/640px-Tai_Bwo_Wannai_Village.png"},{"name":"Brimhaven","rarity":"common","id":"brimhaven","subtitle":"Locations","details":"A pirate town on western Karamja, with a dungeon of metal dragons, an agility arena, a bar and ships sailing to Ardougne and beyond.","image":"https://runescape.wiki/images/thumb/Brimhaven.png/640px-Brimhaven.png"},{"name":"Canifis","rarity":"common","id":"canifis","subtitle":"Locations","details":"A werewolf town in Morytania east of Paterdomus, with a bank, a tannery and a rotten food shop, reached past the holy barrier of the Salve.","image":"https://runescape.wiki/images/thumb/Canifis.png/640px-Canifis.png"},{"name":"Hans","rarity":"common","id":"hans","subtitle":"Gods & NPCs","details":"A servant of Lumbridge Castle who has walked its grounds since the earliest days, timing how long visitors have played.","image":"https://runescape.wiki/images/thumb/Hans.png/640px-Hans.png"},{"name":"Duke Horacio","rarity":"common","id":"duke-horacio","subtitle":"Gods & NPCs","details":"Duke of Lumbridge and ruler of the town, a cautious lord who asks for help against dragons, goblins and dark plots.","image":"https://runescape.wiki/images/thumb/Duke_Horacio.png/640px-Duke_Horacio.png"},{"name":"Aubury","rarity":"common","id":"aubury","subtitle":"Gods & NPCs","details":"Owner of the rune shop in Varrock and a senior researcher of runes who teleports mages to the rune essence mine.","image":"https://runescape.wiki/images/thumb/Aubury.png/640px-Aubury.png"},{"name":"Sedridor","rarity":"common","id":"sedridor","subtitle":"Gods & NPCs","details":"Head wizard of the Wizards' Tower south of Draynor, an archmage who guards rune mysteries and the tower's lore.","image":"https://runescape.wiki/images/thumb/Archmage_Sedridor.png/640px-Archmage_Sedridor.png"},{"name":"Zaff","rarity":"common","id":"zaff","subtitle":"Gods & NPCs","details":"Owner of the staff shop in Varrock square, a cheerful merchant who also supplies the Varrock armoury in secret work.","image":"https://runescape.wiki/images/thumb/Zaff.png/640px-Zaff.png"},{"name":"Thessalia","rarity":"common","id":"thessalia","subtitle":"Gods & NPCs","details":"Owner of the fine clothes store in Varrock square, a seamstress who sells garments and restyles adventurers' outfits.","image":"https://runescape.wiki/images/thumb/Thessalia.png/640px-Thessalia.png"},{"name":"King Arthur","rarity":"common","id":"king-arthur","subtitle":"Gods & NPCs","details":"The legendary king of Camelot, stranded in Gielinor with his Knights of the Round Table while seeking the Holy Grail.","image":"https://runescape.wiki/images/thumb/King_Arthur.png/640px-King_Arthur.png"},{"name":"Lord Amlodd","rarity":"common","id":"lord-amlodd","subtitle":"Gods & NPCs","details":"Leader of the Amlodd Clan of elves in Prifddinas, a shadow caster whose clan masters divination and summoning crafts.","image":"https://runescape.wiki/images/thumb/Lord_Amlodd.png/640px-Lord_Amlodd.png"},{"name":"Father Aereck","rarity":"common","id":"father-aereck","subtitle":"Gods & NPCs","details":"Priest of the Lumbridge Church of Saradomin, an elderly cleric who tends the graveyard and its restless ghost.","image":"https://runescape.wiki/images/thumb/Father_Aereck.png/640px-Father_Aereck.png"},{"name":"Aggie","rarity":"common","id":"aggie","subtitle":"Gods & NPCs","details":"A witch of Draynor Village who brews dyes and pastes for quests, turning berries, ashes and coins into bright colours.","image":"https://runescape.wiki/images/thumb/Aggie.png/640px-Aggie.png"},{"name":"Cook","rarity":"common","id":"cook","subtitle":"Gods & NPCs","details":"The Lumbridge Castle cook, a flustered chef famous for a ruined birthday cake and a plea for cake ingredients.","image":"https://runescape.wiki/images/thumb/Cook_%28Lumbridge%29.png/640px-Cook_%28Lumbridge%29.png"},{"name":"Ellis","rarity":"common","id":"ellis","subtitle":"Gods & NPCs","details":"The tanner of Al Kharid, who cures cowhides and dragonhides into leather for crafters beside the city's furnace.","image":"https://runescape.wiki/images/thumb/Ellis.png/640px-Ellis.png"},{"name":"Apothecary","rarity":"common","id":"apothecary","subtitle":"Gods & NPCs","details":"The apothecary of south-west Varrock, a potion maker who brews strange mixtures from herbs, eggs and odd remains.","image":"https://runescape.wiki/images/thumb/Apothecary.png/640px-Apothecary.png"},{"name":"Sir Amik Varze","rarity":"common","id":"sir-amik-varze","subtitle":"Gods & NPCs","details":"Grand Master of the White Knights of Falador, a senior knight who leads the order from the castle's upper floors.","image":"https://runescape.wiki/images/thumb/Sir_Amik_Varze.png/640px-Sir_Amik_Varze.png"},{"name":"Max","rarity":"common","id":"max","subtitle":"Gods & NPCs","details":"A Varrock cape seller who has mastered every skill to level 99 and sells the coveted Max Cape to those who match him.","image":"https://runescape.wiki/images/thumb/Max.png/640px-Max.png"},{"name":"Ozan","rarity":"common","id":"ozan","subtitle":"Gods & NPCs","details":"A dashing rogue and hero of Al Kharid, a quick-witted bowman who aids adventurers in desert quests and daring heists.","image":"https://runescape.wiki/images/thumb/Ozan.png/640px-Ozan.png"},{"name":"Gypsy Aris","rarity":"common","id":"gypsy-aris","subtitle":"Gods & NPCs","details":"A fortune teller in a Varrock tent who recounts the fall of Delrith and sends adventurers to forge the Silverlight.","image":"https://runescape.wiki/images/thumb/Aris.png/640px-Aris.png"},{"name":"Rune Platebody","rarity":"common","id":"rune-platebody","subtitle":"Gear","details":"Tier 40 melee chest armour smithed from five runite bars, the classic blue platebody worn by generations of mid-level players.","image":"https://runescape.wiki/images/thumb/Rune_platebody_detail.png/512px-Rune_platebody_detail.png"},{"name":"Rune Platelegs","rarity":"common","id":"rune-platelegs","subtitle":"Gear","details":"Tier 40 melee leg armour smithed from three runite bars, paired with the rune platebody in the standard mid-level melee kit.","image":"https://runescape.wiki/images/thumb/Rune_platelegs_detail.png/512px-Rune_platelegs_detail.png"},{"name":"Rune Full Helm","rarity":"common","id":"rune-full-helm","subtitle":"Gear","details":"Tier 40 melee helmet smithed from two runite bars, completing the classic all-rune look for mid-level warriors across Gielinor.","image":"https://runescape.wiki/images/thumb/Rune_full_helm_detail.png/512px-Rune_full_helm_detail.png"},{"name":"Rune Scimitar","rarity":"common","id":"rune-scimitar","subtitle":"Gear","details":"Tier 40 main-hand melee weapon smithed from two runite bars, the go-to fast training weapon for mid-level Attack levels.","image":"https://runescape.wiki/images/thumb/Rune_scimitar_detail.png/512px-Rune_scimitar_detail.png"},{"name":"Rune 2h Sword","rarity":"common","id":"rune-2h-sword","subtitle":"Gear","details":"Tier 40 two-handed melee weapon smithed from three runite bars, hitting slowly but hard for free-to-play and mid-level fighters.","image":"https://runescape.wiki/images/thumb/Rune_2h_sword_detail.png/512px-Rune_2h_sword_detail.png"},{"name":"Dragon Med Helm","rarity":"common","id":"dragon-med-helm","subtitle":"Gear","details":"Tier 60 melee helmet dropped by many strong monsters, the affordable dragon helm worn long before the full helm existed.","image":"https://runescape.wiki/images/thumb/Dragon_helm_detail.png/512px-Dragon_helm_detail.png"},{"name":"Dragon Platelegs","rarity":"common","id":"dragon-platelegs","subtitle":"Gear","details":"Tier 60 melee leg armour dropped by bronze and iron dragons, a prized red legpiece in the classic dragon equipment set.","image":"https://runescape.wiki/images/thumb/Dragon_platelegs_detail.png/512px-Dragon_platelegs_detail.png"},{"name":"Dragon Longsword","rarity":"common","id":"dragon-longsword","subtitle":"Gear","details":"Tier 60 main-hand melee weapon sold in Zanaris after Lost City, a milestone purchase for many mid-level melee players.","image":"https://runescape.wiki/images/thumb/Dragon_longsword_detail.png/512px-Dragon_longsword_detail.png"},{"name":"Dragon Dagger","rarity":"common","id":"dragon-dagger","subtitle":"Gear","details":"Tier 60 main-hand melee weapon sold in Zanaris after Lost City, famous in its poisoned form for a cheap, deadly special attack.","image":"https://runescape.wiki/images/thumb/Dragon_dagger_detail.png/512px-Dragon_dagger_detail.png"},{"name":"Dragon Battleaxe","rarity":"common","id":"dragon-battleaxe","subtitle":"Gear","details":"Tier 60 main-hand melee weapon sold in the Heroes' Guild, boosting Strength with its Rampage special attack when wielded.","image":"https://runescape.wiki/images/thumb/Dragon_battleaxe_detail.png/512px-Dragon_battleaxe_detail.png"},{"name":"Dragon Halberd","rarity":"common","id":"dragon-halberd","subtitle":"Gear","details":"Tier 60 two-handed melee weapon sold in West Ardougne after Regicide, striking from a square away and sweeping large foes.","image":"https://runescape.wiki/images/thumb/Dragon_halberd_detail.png/512px-Dragon_halberd_detail.png"},{"name":"Dragon Boots","rarity":"common","id":"dragon-boots","subtitle":"Gear","details":"Tier 60 melee boots dropped by spiritual mages in the God Wars Dungeon, giving a Strength bonus rare among footwear.","image":"https://runescape.wiki/images/thumb/Dragon_boots_detail.png/512px-Dragon_boots_detail.png"},{"name":"Amulet of Glory","rarity":"common","id":"amulet-of-glory","subtitle":"Gear","details":"Dragonstone amulet enchanted with Lvl-5 Enchant, offering teleports to Edgeville, Karamja, Draynor Village and Al Kharid.","image":"https://runescape.wiki/images/Amulet_of_glory_detail.png"},{"name":"Amulet of Power","rarity":"common","id":"amulet-of-power","subtitle":"Gear","details":"Neck jewellery made by enchanting a diamond amulet, giving balanced combat bonuses across all three styles for a low price.","image":"https://runescape.wiki/images/thumb/Amulet_of_power_detail.png/512px-Amulet_of_power_detail.png"},{"name":"Amulet of Strength","rarity":"common","id":"amulet-of-strength","subtitle":"Gear","details":"Neck jewellery made by enchanting a ruby amulet, prized by melee fighters for its simple, cheap Strength bonus in combat.","image":"https://runescape.wiki/images/Amulet_of_strength_detail.png"},{"name":"Obsidian Cape","rarity":"common","id":"obsidian-cape","subtitle":"Gear","details":"Tier 60 cape woven from obsidian in TzHaar City beneath Karamja's volcano, a sturdy all-round cloak for mid-level players.","image":"https://runescape.wiki/images/thumb/Obsidian_cape_detail.png/512px-Obsidian_cape_detail.png"},{"name":"Fighter Torso","rarity":"common","id":"fighter-torso","subtitle":"Gear","details":"Tier 40 melee chest armour earned with honour points at Barbarian Assault in the Barbarian Outpost, valued for its Strength bonus.","image":"https://runescape.wiki/images/thumb/Fighter_torso_detail.png/512px-Fighter_torso_detail.png"},{"name":"Magic Shortbow","rarity":"common","id":"magic-shortbow","subtitle":"Gear","details":"Tier 50 two-handed bow fletched from a magic shortbow shaft and bow string, a staple ranged weapon with a snap-shot special.","image":"https://runescape.wiki/images/thumb/Magic_shortbow_detail.png/512px-Magic_shortbow_detail.png"},{"name":"Magic Longbow","rarity":"common","id":"magic-longbow","subtitle":"Gear","details":"Tier 50 two-handed bow fletched from magic logs, slower than the shortbow but hitting at a longer range across Gielinor.","image":"https://runescape.wiki/images/thumb/Magic_longbow_detail.png/512px-Magic_longbow_detail.png"},{"name":"Rune Crossbow","rarity":"common","id":"rune-crossbow","subtitle":"Gear","details":"Tier 50 main-hand crossbow fletched from runite limbs and a yew stock, the classic launcher for broad and runite bolts.","image":"https://runescape.wiki/images/thumb/Rune_crossbow_detail.png/512px-Rune_crossbow_detail.png"},{"name":"Black Dragonhide Body","rarity":"common","id":"black-dragonhide-body","subtitle":"Gear","details":"Tier 60 Ranged chest armour crafted from black dragon leather, the standard ranged body for mid-level rangers everywhere.","image":"https://runescape.wiki/images/thumb/Black_dragonhide_body_detail.png/512px-Black_dragonhide_body_detail.png"},{"name":"Mystic Robe Top","rarity":"common","id":"mystic-robe-top","subtitle":"Gear","details":"Tier 50 Magic chest armour bought in the Wizards' Guild in Yanille or dropped by monsters, the classic blue mystic robe top.","image":"https://runescape.wiki/images/thumb/Mystic_robe_top_detail.png/512px-Mystic_robe_top_detail.png"},{"name":"Granite Maul","rarity":"common","id":"granite-maul","subtitle":"Gear","details":"Tier 55 two-handed melee weapon dropped by gargoyles, famous for stacking three near-instant special attacks in PvP combat.","image":"https://runescape.wiki/images/thumb/Granite_maul_detail.png/512px-Granite_maul_detail.png"},{"name":"Helm of Neitiznot","rarity":"common","id":"helm-of-neitiznot","subtitle":"Gear","details":"Tier 55 melee helmet earned on Neitiznot during The Fremennik Isles, offering prayer and Strength bonuses for its level.","image":"https://runescape.wiki/images/thumb/Helm_of_Neitiznot_chathead.png/512px-Helm_of_Neitiznot_chathead.png"},{"name":"Berserker Helm","rarity":"common","id":"berserker-helm","subtitle":"Gear","details":"Tier 45 melee helmet bought in Rellekka after The Fremennik Trials, giving a Strength bonus popular with mid-level fighters.","image":"https://runescape.wiki/images/thumb/Berserker_helm_detail.png/512px-Berserker_helm_detail.png"},{"name":"Warrior Helm","rarity":"common","id":"warrior-helm","subtitle":"Gear","details":"Tier 45 melee helmet bought in Rellekka after The Fremennik Trials, favouring slash defence for mid-level Fremennik warriors.","image":"https://runescape.wiki/images/thumb/Warrior_helm_detail.png/512px-Warrior_helm_detail.png"},{"name":"Ancient Staff","rarity":"common","id":"ancient-staff","subtitle":"Gear","details":"Tier 50 staff bought from Eblis after Desert Treasure, required to autocast Ancient Magicks and wielded across the desert.","image":"https://runescape.wiki/images/thumb/Ancient_staff_detail.png/512px-Ancient_staff_detail.png"},{"name":"Dragon Defender","rarity":"common","id":"dragon-defender","subtitle":"Gear","details":"Tier 60 off-hand melee defender earned in the Warriors' Guild in Burthorpe, the top defender dropped by the guild's cyclopes.","image":"https://runescape.wiki/images/thumb/Dragon_defender_detail.png/512px-Dragon_defender_detail.png"},{"name":"Korasi's Sword","rarity":"common","id":"korasi-s-sword","subtitle":"Gear","details":"Tier 78 main-hand melee weapon earned during The Void Stares Back, striking with a magical special attack tied to the Void Knights.","image":"https://runescape.wiki/images/thumb/Korasi%27s_sword_detail.png/512px-Korasi%27s_sword_detail.png"},{"name":"Hill giant","rarity":"common","id":"hill-giant","subtitle":"Monsters","details":"Hill giants are large brutes in the Edgeville Dungeon and other caves, often farmed for big bones and limpwurt roots.","image":"https://runescape.wiki/images/thumb/Hill_Giant_%281%29.png/640px-Hill_Giant_%281%29.png"},{"name":"Moss giant","rarity":"common","id":"moss-giant","subtitle":"Monsters","details":"Moss giants are moss-covered giants found on Crandor, in the Varrock Sewers and in the Brimhaven Dungeon depths below.","image":"https://runescape.wiki/images/thumb/Moss_giant_%282%29.png/640px-Moss_giant_%282%29.png"},{"name":"Lesser demon","rarity":"common","id":"lesser-demon","subtitle":"Monsters","details":"Lesser demons are red-winged demons found in Melzar's Maze, Karamja Volcano and the Wilderness, common foes for trainees.","image":"https://runescape.wiki/images/thumb/Lesser_demon.png/640px-Lesser_demon.png"},{"name":"Greater demon","rarity":"common","id":"greater-demon","subtitle":"Monsters","details":"Greater demons are large horned demons in the Brimhaven Dungeon, Entrana Dungeon and Wilderness, stronger than lessers.","image":"https://runescape.wiki/images/thumb/Greater_demon.png/640px-Greater_demon.png"},{"name":"Black demon","rarity":"common","id":"black-demon","subtitle":"Monsters","details":"Black demons are hulking dark demons in Taverley Dungeon, the Edgeville Dungeon and Brimhaven, with very high health.","image":"https://runescape.wiki/images/thumb/Black_demon.png/640px-Black_demon.png"},{"name":"Hellhound","rarity":"common","id":"hellhound","subtitle":"Monsters","details":"Hellhounds are demonic dogs in Taverley Dungeon, the Wilderness and Stronghold of Safety, guarding clue scroll trails.","image":"https://runescape.wiki/images/thumb/Hellhound.png/640px-Hellhound.png"},{"name":"Rock crab","rarity":"common","id":"rock-crab","subtitle":"Monsters","details":"Rock crabs are disguised crabs on the Rellekka coast that look like boulders until a passing adventurer wakes them up.","image":"https://runescape.wiki/images/thumb/Rock_Crab.png/640px-Rock_Crab.png"},{"name":"Yak","rarity":"common","id":"yak","subtitle":"Monsters","details":"Yaks are shaggy pack animals raised in Neitiznot, commonly trained on for their fast respawns and steady experience.","image":"https://runescape.wiki/images/thumb/Yak.png/640px-Yak.png"},{"name":"Green dragon","rarity":"common","id":"green-dragon","subtitle":"Monsters","details":"Green dragons are the weakest chromatic dragons, found in the Wilderness and Corsair Cove, prized for hides and bones.","image":"https://runescape.wiki/images/thumb/Green_dragon_1.png/640px-Green_dragon_1.png"},{"name":"Blue dragon","rarity":"common","id":"blue-dragon","subtitle":"Monsters","details":"Blue dragons are chromatic dragons in Taverley Dungeon, the Corsair Cove dungeon and the Heroes' Guild basement caves.","image":"https://runescape.wiki/images/thumb/Blue_dragon.png/640px-Blue_dragon.png"},{"name":"Red dragon","rarity":"common","id":"red-dragon","subtitle":"Monsters","details":"Red dragons are chromatic dragons in the Brimhaven Dungeon, Red Dragon Isle and the Wilderness, guarding their hoards.","image":"https://runescape.wiki/images/thumb/Red_dragon_%281%29.png/640px-Red_dragon_%281%29.png"},{"name":"Black dragon","rarity":"common","id":"black-dragon","subtitle":"Monsters","details":"Black dragons are the strongest chromatic dragons, found in Taverley Dungeon, the Wilderness and the Evil Chicken's lair.","image":"https://runescape.wiki/images/thumb/Black_dragon.png/640px-Black_dragon.png"},{"name":"Cockatrice","rarity":"common","id":"cockatrice","subtitle":"Monsters","details":"Cockatrice are Slayer monsters in the Rellekka Slayer Caves whose gaze can drain stats, blocked by a mirror shield.","image":"https://runescape.wiki/images/thumb/Cockatrice.png/640px-Cockatrice.png"},{"name":"Basilisk","rarity":"common","id":"basilisk","subtitle":"Monsters","details":"Basilisks are Slayer monsters in the Rellekka Slayer Caves and Pollnivneach dungeon, their gaze blocked by a mirror shield.","image":"https://runescape.wiki/images/thumb/Basilisk.png/640px-Basilisk.png"},{"name":"Kurask","rarity":"common","id":"kurask","subtitle":"Monsters","details":"Kurasks are leafy Slayer monsters in the Rellekka Slayer Caves and Pollnivneach dungeon, hurt only by leaf-bladed weapons.","image":"https://runescape.wiki/images/thumb/Kurask.png/640px-Kurask.png"},{"name":"Turoth","rarity":"common","id":"turoth","subtitle":"Monsters","details":"Turoths are plant-like Slayer monsters in the Rellekka Slayer Caves, hurt only by leaf-bladed weapons and broad bolts.","image":"https://runescape.wiki/images/thumb/Turoth_%28young%29.png/640px-Turoth_%28young%29.png"},{"name":"Warped tortoise","rarity":"common","id":"warped-tortoise","subtitle":"Monsters","details":"Warped tortoises are tortoises twisted by poison in the Poison Waste sewers, cleaned with crystal chimes before combat.","image":"https://runescape.wiki/images/thumb/Warped_tortoise.png/640px-Warped_tortoise.png"},{"name":"Dagannoth","rarity":"common","id":"dagannoth","subtitle":"Monsters","details":"Dagannoth are walrus-like sea creatures beneath the Lighthouse and on Waterbirth Island, attacking in all three styles.","image":"https://runescape.wiki/images/thumb/Dagannoth_ranged.png/640px-Dagannoth_ranged.png"},{"name":"Kalphite worker","rarity":"common","id":"kalphite-worker","subtitle":"Monsters","details":"Kalphite workers are the smallest kalphites in the Kalphite Hive near Al Kharid, swarming intruders who enter the nest.","image":"https://runescape.wiki/images/thumb/Kalphite_Worker.png/640px-Kalphite_Worker.png"},{"name":"Banshee","rarity":"common","id":"banshee","subtitle":"Monsters","details":"Banshees are wailing undead Slayer monsters in the Slayer Tower, requiring earmuffs to protect against their screams.","image":"https://runescape.wiki/images/thumb/Banshee.png/640px-Banshee.png"},{"name":"Crawling hand","rarity":"common","id":"crawling-hand","subtitle":"Monsters","details":"Crawling hands are severed hands crawling the Slayer Tower floors, from zombie and skeleton hands reanimated by dark magic.","image":"https://runescape.wiki/images/thumb/Crawling_Hand.png/640px-Crawling_Hand.png"},{"name":"Jelly","rarity":"common","id":"jelly","subtitle":"Monsters","details":"Jellies are gelatinous Slayer monsters in the Rellekka Slayer Caves and Chaos Tunnels, wobbling toward their victims.","image":"https://runescape.wiki/images/thumb/Jelly.png/640px-Jelly.png"},{"name":"Earth warrior","rarity":"common","id":"earth-warrior","subtitle":"Monsters","details":"Earth warriors are warriors of dirt and stone in the Edgeville Dungeon's Wilderness section, guarding the bronze gate area.","image":"https://runescape.wiki/images/thumb/Earth_warrior.png/640px-Earth_warrior.png"},{"name":"Green Hallowe'en Mask","rarity":"common","id":"green-hallowe-en-mask","subtitle":"Items","details":"A green mask dropped only on 31 October 2002, one of three spooky colours that became discontinued holiday treasure.","image":"https://runescape.wiki/images/Green_hallowe%27en_mask_detail.png"},{"name":"Blue Hallowe'en Mask","rarity":"common","id":"blue-hallowe-en-mask","subtitle":"Items","details":"A blue mask dropped only on 31 October 2002, completing the trio of colours with its red and green counterparts.","image":"https://runescape.wiki/images/Blue_hallowe%27en_mask_detail.png"},{"name":"Ice Dye","rarity":"common","id":"ice-dye","subtitle":"Items","details":"A dye from elite Treasure Trails that recolours high-level gear in a pale, frozen blue, consumed when applied.","image":"https://runescape.wiki/images/Ice_dye_detail.png"},{"name":"Easter Egg","rarity":"common","id":"easter-egg","subtitle":"Items","details":"A chocolate egg from an early Easter drop that players were meant to eat; the uneaten survivors became collectable rares.","image":"https://runescape.wiki/images/Easter_egg_detail.png"},{"name":"Pumpkin","rarity":"common","id":"pumpkin","subtitle":"Items","details":"A pumpkin dropped at an early Halloween as a healing treat; the ones that were never eaten became treasured collectables.","image":"https://runescape.wiki/images/thumb/Pumpkin_detail.png/640px-Pumpkin_detail.png"},{"name":"Dragon Bones","rarity":"common","id":"dragon-bones","subtitle":"Items","details":"Bones dropped by dragons, buried or offered at altars for some of the fastest Prayer experience available to trainers.","image":"https://runescape.wiki/images/thumb/Dragon_bones_detail.png/640px-Dragon_bones_detail.png"},{"name":"Shark","rarity":"common","id":"shark","subtitle":"Items","details":"A fish caught by harpoon that cooks into a dependable healing food, carried in stacks into countless boss fights.","image":"https://runescape.wiki/images/thumb/Shark_detail.png/640px-Shark_detail.png"},{"name":"Rune Essence","rarity":"common","id":"rune-essence","subtitle":"Items","details":"Uncharged essence mined in the rune essence mine, carried to altars and turned into the runes that power all magic.","image":"https://runescape.wiki/images/thumb/Rune_essence_detail.png/640px-Rune_essence_detail.png"},{"name":"Coins","rarity":"common","id":"coins","subtitle":"Items","details":"The universal currency of Gielinor, stacked in pouches and chests and spent on gear, supplies, and Grand Exchange trades.","image":"https://runescape.wiki/images/thumb/Coins_1000_detail.png/640px-Coins_1000_detail.png"},{"name":"Logs","rarity":"common","id":"logs","subtitle":"Items","details":"Ordinary logs cut from regular trees, burned, fletched, and built with as the humble starting point of several skills.","image":"https://runescape.wiki/images/thumb/Logs_detail.png/640px-Logs_detail.png"},{"name":"Coal","rarity":"common","id":"coal","subtitle":"Items","details":"A black mineral mined across the world, long burned in furnaces and used to smelt the mid-tier metals of Smithing.","image":"https://runescape.wiki/images/thumb/Coal_detail.png/640px-Coal_detail.png"},{"name":"Great Orb Project","rarity":"common","id":"great-orb-project","subtitle":"Activities","details":"A Runecrafting activity at the altars, where two teams use wands to attract or repel coloured orbs to score points.","image":"https://runescape.wiki/images/thumb/The_Great_Orb_Project.png/640px-The_Great_Orb_Project.png"},{"name":"Trouble Brewing","rarity":"common","id":"trouble-brewing","subtitle":"Activities","details":"A pirate brewing contest on Mos Le'Harmless, where two crews gather water, flowers and monkeys to brew the best ale.","image":"https://runescape.wiki/images/thumb/Trouble_Brewing_red_base.png/640px-Trouble_Brewing_red_base.png"},{"name":"Conquest","rarity":"common","id":"conquest","subtitle":"Activities","details":"A turn-based strategy activity commanding squads of Void Knight units on a grid against another player's army.","image":"https://runescape.wiki/images/thumb/Conquest.png/640px-Conquest.png"},{"name":"Big Chinchompa","rarity":"common","id":"big-chinchompa","subtitle":"Activities","details":"A Hunter activity with the gnome Nyriki, feeding soporith moths to a ravenous chinchompa until it finally bursts.","image":"https://runescape.wiki/images/thumb/Big_Chinchompa.png/640px-Big_Chinchompa.png"},{"name":"Evil Tree","rarity":"common","id":"evil-tree","subtitle":"Activities","details":"A woodcutting event where a corrupted tree sprouts across Gielinor and must be chopped, burned and reported for rewards.","image":"https://runescape.wiki/images/thumb/Evil_tree_DnD.png/640px-Evil_tree_DnD.png"},{"name":"Shooting Star","rarity":"common","id":"shooting-star","subtitle":"Activities","details":"A Mining event where a fallen star lands across Gielinor, mined in layers for stardust traded to a star sprite.","image":"https://runescape.wiki/images/thumb/Crashed_star_%28size_4%29.png/640px-Crashed_star_%28size_4%29.png"},{"name":"God Statues","rarity":"common","id":"god-statues","subtitle":"Activities","details":"A monthly Construction activity raising scaffolded statues of gods at holy sites for Construction and Prayer rewards.","image":"https://runescape.wiki/images/thumb/Statue_of_Zilyana_%28level_1%2B%29.png/640px-Statue_of_Zilyana_%28level_1%2B%29.png"},{"name":"Troll Invasion","rarity":"common","id":"troll-invasion","subtitle":"Activities","details":"A monthly defence at Burthorpe where waves of mountain trolls march on the gate and must be repelled for a reward book.","image":"https://runescape.wiki/images/thumb/Troll_Invasion.png/640px-Troll_Invasion.png"},{"name":"Cabbage Facepunch Bonanza","rarity":"common","id":"cabbage-facepunch-bonanza","subtitle":"Activities","details":"A gorilla-gladiator activity where players punch cabbage-faced foes, dodge Brassica's wrath and earn Slayer points.","image":"https://runescape.wiki/images/thumb/Cabbage_Facepunch_Bonanza.png/640px-Cabbage_Facepunch_Bonanza.png"},{"name":"Flash Powder Factory","rarity":"common","id":"flash-powder-factory","subtitle":"Activities","details":"An agility and thieving activity in a rogues' factory, mixing flash powder to order while dodging its hazards.","image":"https://runescape.wiki/images/thumb/Flash_Powder_Factory.png/640px-Flash_Powder_Factory.png"},{"name":"Sorceress's Garden","rarity":"common","id":"sorceress-s-garden","subtitle":"Activities","details":"A thieving garden in Al Kharid where sneaks dodge elementals to pick sq'irk fruit from seasonal trees for juice.","image":"https://runescape.wiki/images/thumb/Sorceress%27s_Garden.png/640px-Sorceress%27s_Garden.png"},{"name":"Balthazar Beauregard's Big Top Bonanza","rarity":"common","id":"balthazar-beauregard-s-big-top-bonanza","subtitle":"Activities","details":"A weekly circus in a roaming big top, performing agility, magic and ranged feats for the ringmaster Balthazar.","image":"https://runescape.wiki/images/thumb/Circus.png/640px-Circus.png"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
